"C:\\Program Files\\WindowsApps\\OpenAI.CodexPrimaryRuntime.v26-1104-2876-0_26.1104.2876.0_x64__3k8sg7r9htsxt\\dependencies\\native\\powershell\\pwsh.exe" -Command '$criteria = Get-Content -LiteralPath criteria.md -Raw
$headings = @([regex]::Matches($criteria, '"'(?m)"'^## .+$'"') | ForEach-Object { "'$_.Value.Trim() })
$expectedHeadings = @('"'## Checks', '## Score mapping', '## Worked examples', '## Failure modes')
if (("'$headings -join '"'|') -ne ("'$expectedHeadings -join '"'|')) { throw 'Unexpected headings' }
if ([regex]::Matches("'$criteria, '"'(?m)"'^'"\\d+\\. \\*\\*C\\d+').Count -ne 8) { throw 'Unexpected check count' }
"'$expectedHashes = @{
 '"'CAL-A.txt' = 'CD45BC45A390A940C4ABC3E4E8225043BEDBE47BBC60EDA1577A088E0291E734'
 'CAL-B.txt' = '54F9F2B99D0E9788879D529E168EEA371B0EA81E5577CE3A8E88098CF94B76EF'
 'CAL-C.txt' = '48867AAF20E515D4C2EC0F327B670E5EBFB5574657A5B437B01A4DE616766FF7'
 'CAL-D.txt' = '6EC8CE50D36AAC0660445FAE9AF24C0231438FE62B5F27B4B5B46EB8A8D87D3E'
}
foreach ("'$name in $expectedHashes.Keys) {
 if ((Get-FileHash -LiteralPath (Join-Path input $name)).Hash -ne $expectedHashes[$name]) { throw "Calibration changed: $name" }
}
Get-ChildItem -File | Select-Object Name
Write-Output '"'Verified four headings, eight checks, and unchanged calibration files.'"

